const threshold = Number($env.SOURCE_SCORE_THRESHOLD || 5);
const results = $json.results || $json.sources || [];
const officialDomains = ['who.int', 'unicef.org', 'has-sante.fr', 'santepubliquefrance.fr', 'nhs.uk', 'cdc.gov'];

function domainFromUrl(url) {
  try { return new URL(url).hostname.replace(/^www\./, ''); } catch { return ''; }
}

function scoreSource(source) {
  const domain = source.domain || domainFromUrl(source.url || '');
  let score = 0;
  let sourceType = source.sourceType || 'Unknown';
  const reasons = [];

  if (officialDomains.some(official => domain === official || domain.endsWith(`.${official}`))) {
    score += 5;
    sourceType = domain === 'who.int' || domain === 'unicef.org' ? 'HealthAuthority' : 'Official';
    reasons.push('Recognized official or health authority domain.');
  }
  if (!source.publicationDate && !source.date) {
    score -= 2;
    reasons.push('Missing publication date.');
  }
  if (!source.author) {
    score -= 3;
    reasons.push('Missing author.');
  }
  if (source.commercial === true) {
    score -= 3;
    sourceType = 'Commercial';
    reasons.push('Commercial content signal.');
  }

  return {
    title: source.title || source.name || 'Untitled source',
    url: source.url || '',
    domain,
    publisher: source.publisher || null,
    publicationDate: source.publicationDate || source.date || null,
    author: source.author || null,
    sourceType,
    score,
    accepted: Boolean(source.url) && score >= threshold,
    reason: reasons.length ? reasons.join(' ') : 'No strong reliability signal found.',
    readingTimeMinutes: source.readingTimeMinutes || null,
    summary: source.summary || null
  };
}

const sources = results.map(scoreSource);
const accepted = sources.filter(source => source.accepted).length;

return [{
  json: {
    sources,
    summary: {
      total: sources.length,
      accepted,
      rejected: sources.length - accepted
    }
  }
}];
